from langchain_core.prompts import ChatPromptTemplate
from langchain_google_genai import ChatGoogleGenerativeAI
from src.graph.state import AgentState

llm_pro = ChatGoogleGenerativeAI(model="gemini-1.5-pro", temperature=0.1)

def consensus_node(state: AgentState) -> dict:
    """Generates a unified healthcare-assistance response from the debate."""
    
    prompt = ChatPromptTemplate.from_messages([
        ("system", (
            "You are the Consensus Agent in a multi-agent healthcare system. "
            "You receive the outputs generated by the specialist agents and the debate stage. "
            "Your objective is to produce a unified response by considering specialist opinions, "
            "degree of agreement, available patient information, and uncertainty. "
            "Do not establish a definitive medical diagnosis. Generate a structured healthcare-assistance response."
        )),
        ("human", (
            "Raw Symptoms: {raw_symptoms}\n"
            "Patient History: {patient_history}\n"
            "Specialist Assessments: {specialist_assessments}\n"
            "Debate Output: {debate_output}"
        ))
    ])
    
    chain = prompt | llm_pro
    result = chain.invoke({
        "raw_symptoms": state.get("raw_symptoms", ""),
        "patient_history": state.get("patient_history", []),
        "specialist_assessments": state.get("specialist_assessments", {}),
        "debate_output": state.get("debate_output", {})
    })
    
    return {"consensus_draft": result.content}